@module sonority  src=sonority.lua  loc=1245  mode=namespace  self=sonority

# Invariants & contracts
  @invariant  pure module: no state; ratios/cents are tuning.lua's, the placement carries them  @ 4
  @contract  members; seat/presence/mayWait per strand; moves/width/stiffness → Spellings, best first  @ 746
  @contract  a join is one move; a spelling states intervals, and stands at any offset from the seats  @ 747
  @contract  the width is a width per waiting count; math.huge enumerates the spellings whole  @ 748
  @contract  a target stating no move spells nothing: the list is empty  @ 749
  @invariant  what has closed is carried, which is what retaking it a cursor later would charge  @ 1154
  @invariant  an answer's debts stand in onset order, as the walk opens them and closes them in it  @ 1157
  @contract  onsets, a spelling list per onset, seat per strand, strength, stiffness, cap, ambient  @ 1158
  @contract  → the cheapest Answer, every answer carried extended by every spelling of the onset  @ 1159
  @contract  the strands the onset sounds relax; the rest of an answer stands at the cents it carries  @ 1160
  @contract  a strand born at an onset rests on its share of where the sonority before it stood  @ 1161
  @contract  a sonority holding a waiter is charged in its own onset's slot, as its members place  @ 1162
  @contract  answers agreeing to half a cent ahead and owing the same merge; the set is cut to cap  @ 1163
  @contract  answers resting apart at an open strand are two, a rest deciding what its pull costs  @ 1164
  @contract  the cut runs over two pools, the answers that owe and the answers that have paid  @ 1165
  @contract  nil where an onset has no spelling — which is a target stating no move  @ 1166

# Shapes
  @shape  Coords = {[oddPrime]=exponent}; prime 2 is absent, so the score reads harmony not spacing  @ 5
  @shape  Strand = { notes={ {ppq,pitch,endppq,..},.. }, class=<step-class>, shortlist={ Candidate,.. } }; the walk reads the strikes, the releases and the class  @ 6
  @shape  Sonority = { ppq, strands={ strandIndex,.. } }; most recently struck first, the last n struck and whatever else still sounds  @ 7
  @shape  Candidate = { coords=Coords, strain=<distance from the written step, in half-windows> }  @ 8
  @shape  Spring = { i=<strand>, j=<strand>, delta=<cents>, weight=<its two members' presence, multiplied> }; the pair is pure where d[j] - d[i] = delta  @ 302
  @shape  Ties = { [strand] = { other, other, .., weights={ weight, .. }, count, delta=<the weighted tie deltas summed>, weight=<the weights summed> } }  @ 366
  @shape  Candidate = { from=State, slot, placed=Placed|nil, token, key, score, waits }  @ 525
  @shape  State = { at={ [slot]=Placed }, components={ {slot,..},.. }, parts, key, waits, score }  @ 526
  @shape  Placed = { coords=Coords, cents=<the pure position>, deviation=<from the seat>, presence, component }  @ 527
  @shape  Spelling = { box=<what its components carry>, springs={Spring,..}, waiting={member,..}, placed={ [strand]={ coords=Coords, component } } }  @ 745
  @shape  Onset = { ppq, members={strand,..}, sounding={strand,..}, presence={[strand]=<1 or RECENT>}, mayWait={[strand]=true,..} }  @ 784
  @shape  Answer = { choice={ spelling per onset }, springs={ Spring list per onset }, box, displacement, cost, closed=<what the shut onsets charge>, held={ Held,.. }, rest={ [strand]=<cents> } }  @ 1155
  @shape  Held = { onset, placed={ [strand]={ coords=Coords, component } }, waiting={ [strand]=true }, box=<charged so far> }  @ 1156

# Imports
  @const util = 'util'  @ 10
  @const tuning = 'tuning'  @ 11

# Module-level constants
  @const sonority = {}  @ 12
  @const budget = 200000  @ 186
  @const PURE = 50  @ 324
  @const TOLERANCE, SWEEPS = 1e-4, 1000  @ 361
  @const abs = math.abs  @ 362   -- the sweep calls it repeatedly
  @const axisWeight = {}  @ 479
  @const DEFERRED = '?'  @ 513
  @const RECENT = 0.5  @ 780
  @const AUDIBLE = 0.5  @ 814
  @const WIDTH, CAP = 24, 6  @ 1218

# Private functions
  -- The box
  -- The strands
  -- The walk
  @fn strikesInOrder(strands)  @ 76-89
      -- Every strike, in onset order, lowest last — so a released chord leaves its
      -- bass to the sonority that follows (§ The walk).
  @fn sounding(strand, ppq)  @ 93-98
      -- Half-open, so a note released where the next is struck does not sound there,
      -- and a passage whose notes stop as the next begin reads as the last n struck.
  @fn promote(recent, strands, index)  @ 102-108
      -- The class holds one entry however many notes write it: a restrike moves its
      -- own entry to the front, and a second strand of the class takes the entry over.
  -- The objective
  -- The solve
  @fn schedule(strands, sonorities)  @ 156-182
      -- A strand is live from the onset it is chosen at to the last that reads it, both
      -- known before enumeration (design/adaptive-tuning.md § Solving it), and listed in strand order for keying.
      @contract  strands, sonorities → per onset the strands born there, live there, and held from before  @ 155
  @fn assertAffordable(strands, plan)  @ 188-198
  @fn placementsAt(strands, born, strength)  @ 202-221
      -- Every combination of the shortlists of the strands born at an onset, with the
      -- pull each charges — the same against every state, so charged once here.
  @fn outranks(state, best, count, rankOf)  @ 226-234
      -- Cost, then the strands one by one, so an exact tie breaks deterministically rather than
      -- by table order (design/adaptive-tuning.md § What the solver takes).
      @contract  true iff `state` is the better of the two, the lower rank winning a tie  @ 225
  @fn byChoice(state, index)  @ 237-239
      -- Ranks a strand by the candidate index the solve chose for it.
  @fn keyOf(choice, list)  @ 241-245
  -- The springs
  -- The relaxation
  @fn settle(ties, displacement, strength, stiffness, rest)  @ 408-414
      -- One strand's optimum with its neighbours held: what its springs ask of it against its
      -- rest, the two dials weighting them and the fifty both are charged over dividing out.
  -- The candidates
  @fn joinCoords(coords, move)  @ 439-447
      -- A join's coords: the host's plus the move's, a cancelled prime dropped so two chains
      -- arriving at one spelling key alike (§ The candidates).
  @fn rebase(coords, from, to)  @ 451-460
      -- Coords are differences, so reading a member in another frame is one vector shift: what
      -- stood at `from` stands at `to`, a cancelled prime dropped as joinCoords drops it.
  @fn coordString(coords)  @ 463-469
      -- Coords in one order, so two tables holding the same exponents read alike.
  @fn tokenOf(placed)  @ 473-475
      -- What a state has made of a member: the coords it was spelled at, and the component it
      -- joined into, so a member in a component of its own reads apart from the same coords tied in.
  @fn weightOf(prime)  @ 480-484
  @fn joinCost(state, component, placed, stiffness, spans)  @ 490-510
      -- What a join costs where it lands: what it widens its component's box by over the box that
      -- component came in carrying, and a spring against each member already there (§ The candidates).
      -- The widening is read off the component's spans: an axis the join does not name it widens
      -- to hold a zero, priced once in the spans' zeroDelta, so only its own axes are visited.
  @fn byScore(a, b)  @ 517-520
      -- Score, then the spelling itself, so an exact tie breaks on the coords rather than on
      -- table order, as sonority.solveToPoints breaks its own.
  @fn admit(best, width, state, slot, placed, token, key, stiffness, spans)  @ 529-551
      -- Scored once its key is new, so a candidate repeating a spelling costs nothing past the
      -- key, and only a candidate its cut keeps is built: joining widens and never narrows, so a
      -- state already scoring past a full bucket's worst is refused before it is priced.
      @invariant  no two members take one spelling, so a sonority states as many pitches as members  @ 528
  @fn materialise(candidate)  @ 554-567
      -- The state a candidate names, built once the cut has kept it.
  @fn beamOver(seat, free, presence, moves, width, stiffness)  @ 574-685
      -- One round per member decides one slot: a move to a member already placed, or left waiting.
      -- Every road decides the same slots, so a differing order's duplicates collapse where they land.
      @invariant  a round decides one slot, so the states it cuts between have placed equally many  @ 571
      @invariant  the first member to place anchors and those before it wait, so one anchor spells each  @ 572
      @invariant  every state ties every member it places; an untied one states nothing, charges none  @ 573
  @fn chargeOf(members, seat, presence, placed)  @ 691-724
      -- What coords and seats state about a set of members: a spring per pair of a component,
      -- tied in member order as sonority.springs ties them, and the box a component carries.
      @contract  members, seat/presence per strand, coords/component per placed member → springs, box  @ 689
      @contract  a member the map lacks is one still waiting, which states nothing and is passed over  @ 690
  @fn spellingOf(state, members, seat, presence)  @ 728-741
      -- The state read back as the sonority's own: its members' coords under the strands they
      -- name, whom it left waiting, and what those state charged as any set of placed members is.
  -- The terms
  -- The search
  @fn visibleAhead(onsets)  @ 818-835
      -- The strands a later onset names and the walk has already moved, in strand order: all a
      -- continuation can read, since what nothing ahead names is settled and what nothing behind has sounded stands at zero alike (§ The solve).
  @fn soundingRuns(onsets)  @ 840-850
      -- The same run read the other way: an onset's strands split into those a later onset sounds
      -- too, which the relaxation can still move, and those it sounded last, which have stopped.
      @contract  onsets → per onset the strands it leaves moving and the strands it closes  @ 839
  @fn bornIn(onsets)  @ 854-866
      -- Which strands each onset first names, in strand order: where a rest is read, a rest
      -- being fixed at the birth of the strand that carries it (§ The solve).
  @fn restsAt(answer, onsets, at, born, share)  @ 872-888
      -- A share of where the music stood as a strand's note arrived: the sonority before the one
      -- it is born into, its members weighted by presence, off the cents the answer carried in.
      @invariant  a member of the onset before has settled there, so nothing unplaced is read  @ 870
      @contract  answer, onsets, the onset, the strands born there, the share → its rests, one per birth  @ 871
  @fn openFrom(onsets)  @ 894-907
      -- A strand sounds over one run of onsets, so once the walk is past every strand an onset
      -- named, nothing it charges can move again: the onsets before the cursor are closed.
      @invariant  the cursor only advances, so a closed onset stays closed for the rest of the walk  @ 892
      @contract  onsets → per onset the earliest onset a strand sounding there is named at  @ 893
  @fn diffString(coords, from)  @ 911-925
      -- The difference of two coords read straight to its string: what coordString would read
      -- of the rebase, fused so a key costs no intermediate table.
  @fn placementKey(members, placed, waiting)  @ 930-957
      -- What a sonority has been spelled as, however the spelling was reached: each component
      -- read from its earliest member, as chargeOf reads it, and the members still waiting.
      @invariant  two placements under one key charge alike, so a wait reaching one is no second road  @ 929
  @fn offeredBy(onsets, spellings)  @ 961-972
      -- What each onset's beam returned, read as placements: the spellings a wait may not come
      -- back with, taken from what the beam kept rather than what its moves could have reached.
  @fn answerKey(displacement, rest, ahead, open, onsets, held)  @ 978-996
      -- An answer keyed by what a continuation can tell it by: cents at the strands ahead, rests
      -- its open strands owe, and the deferrals it has yet to pay.
      @invariant  one strand list serves every answer of an onset, so its cents key by position  @ 976
      @invariant  an open strand sounds, so it was born and carries a rest  @ 977
  @fn complete(entry, members, spelling)  @ 1002-1046
      -- What a spelling makes of a sonority still waiting: a waiter it places takes coords in the
      -- held sonority's frame through a member the two share, and nothing where they share none.
      @invariant  a waiter reaching two components merges them, every member shifted into the one frame  @ 1000
      @invariant  a waiter tied to no member states no interval there, so its completion fails  @ 1001
  @fn heldBy(spelling, at)  @ 1050-1054
      -- The entry a spelling that defers opens: which onset owes it, what it placed, whom it
      -- left, and what it has been charged so far.
  @fn settledOnsets(answer, from, at)  @ 1058-1065
      -- The onsets behind the cursor an answer has settled: the open ones, less any a deferral
      -- still rewrites, so what every spelling of the next onset reads alike is tied once.
  @fn cutBar(cap)  @ 1070-1094
      -- Where a pool's cut now sits: the cost of its cap-th best distinct key, held in a
      -- bounded sorted list, a listed key replaced where it improved (§ The solve).
      @invariant  a key's cost in reached only improves, so a stale bar is only ever too high  @ 1069
  @fn extend(answer, spelling, onsets, at, seat, strength, stiffness, rest, offered, carried, from, since, moving, stopped, bars)  @ 1101-1150
      -- One answer extended by one spelling: the springs and box it has paid, each sonority it
      -- still holds charged again for what this spelling places, the onset's own strands relaxed.
      @contract  carried: the Ties over what the answer has settled, which this spelling's start from  @ 1098
      @contract  nil where a wait comes back with a placement its own sonority offered (§ The candidates)  @ 1099
      @contract  nil where a wait lands tied to no member of the sonority that deferred it  @ 1100

# Public API (sonority.*)
  @api sonority.score(coordSet)  @ 19-34
      -- The axes are gathered before any is measured, so an axis no member names doesn't reach
      -- back to 0; the spans are the octave-free lcm/gcd's coords, whose height tuning.height gives.
      @contract  coords[] → tuning.height of the coords of the set's octave-free lcm/gcd  @ 18
  @api sonority.strands(notes, classOf)  @ 42-70
      -- Notes of a class that overlap hold one tuning (§ The strand); the running
      -- release is half-open, so a note struck at a release starts another.
      @contract  notes, classOf → a Strand per class per run of overlapping notes, shortlists unfilled  @ 40
      @contract  grouped by ascending class, each in strike order, whatever order the notes arrive in  @ 41
  @api sonority.walk(strands, n)  @ 113-128
      -- The whole onset is absorbed before the sonority is taken, so a chord wider
      -- than n leaves its own lowest notes standing rather than its predecessor's.
      @contract  strands, n → a Sonority per onset: last n distinct classes struck, plus sounding  @ 112
  @api sonority.cost(strands, n, strength, choice)  @ 135-149
      -- The pull is counted once per strand rather than once per note, so an octave
      -- doubling changes no answer: the box already charges it nothing.
      @contract  strands, n, strength, choice → box over the walk + strength × strain² per strand  @ 134
  @api sonority.solveToPoints(strands, n, strength)  @ 251-296
      -- The state carries the whole choice vector rather than a backpointer: two
      -- generations are alive at a time and the budget bounds them.
      @invariant  reads no cents and knows no ratios — coords/strikes/releases/classes → indices  @ 249
      @contract  strands, n, strength → the index per strand minimising sonority.cost, exactly  @ 250
  @api sonority.springs(members, seat, presence, spelling)  @ 305-320
      -- Each member's pure position is the first's seat plus its coords' cents; a spring's delta
      -- is the difference of the nearest-octave gaps to each seat (§ The springs).
      @contract  members, spelling per member; seat/presence per strand → a Spring per pair, i before j  @ 303
      @contract  springs alone: a spelling's box is sonority.score(spelling), charged where it is chosen  @ 304
  @api sonority.springCost(spellings, displacement, stiffness, from, to)  @ 333-342
      -- What a run of sonorities' springs charge: each spring against the gap its two strands
      -- would sound pure at, the pair standing where the displacements put them.
      @contract  spellings (a sonority.springs list per sonority) and displacement per strand  @ 331
      @contract  from, to → weight × stiffness × (mistuning/50)² per spring of those onsets  @ 332
  @api sonority.pullCost(displacement, rest, strength, strands)  @ 348-355
      -- What the pull charges: each strand's displacement from its rest, over the fifty the springs
      -- are charged over, a notation's own spacing measuring nothing here (§ The pull).
      @contract  displacement per strand, rest per strand, strands: the ones to charge  @ 346
      @contract  → strength × strain² apiece, strain = (displacement − rest) / 50  @ 347
  @api sonority.ties(springs, free, onsets, base)  @ 370-404
      -- Where each spring would stand its two strands, given the other: i a delta below j, j a
      -- delta above i, gathered for the strands that sweep since a held strand reads only its neighbours' ties, pre-summed since they stand still while the sweeps run.
      @contract  springs per onset, the strands that sweep, the onsets to tie (all of them by default)  @ 367
      @contract  base: a Ties to start from, carried whole, over onsets this call does not tie again  @ 368
      @contract  → a Ties: the base's, and what those onsets' springs tie on top of it  @ 369
  @api sonority.relax(ties, strength, stiffness, start, rest, free)  @ 419-433
      @invariant  convex in the displacements, so the sweep order and the start buy speed, not the answer  @ 416
      @contract  ties, strength, stiffness, start and rest (per strand), free (strands that sweep)  @ 417
      @contract  → displacements minimising springCost + pullCost, held strands at their start  @ 418
  @api sonority.spellings(members, seat, presence, mayWait, moves, width, stiffness)  @ 750-763
      -- A waiting member states no interval, so waiting is a choice the beam makes per member; a
      -- deferral is no rival to a spelling, so the cut runs within a waiting count (§ The candidates).
  @api sonority.seats(strands, notation)  @ 770-776
      -- One seat serves a strand in every register, so notes[1] speaks for all of them; the
      -- seat keeps the register it was written in, which tuning.gapTo quotients out again.
      @contract  strands, notation → the cents of each strand's written step  @ 769
  @api sonority.onsets(strands, sonorities)  @ 787-808
      -- A member is free to wait while an onset it sounds through is still to come; at that onset
      -- it places or the state fails (§ The candidates).
      @contract  strands, sonorities → an Onset per sonority, its members the walk's own  @ 785
      @contract  a member the sonority holds by recency has stopped: it neither sounds nor waits  @ 786
  @api sonority.search(onsets, spellings, seat, strength, stiffness, cap, ambient)  @ 1167-1212
      -- The cost is taken over every spring accumulated so far rather than the onset's own, so
      -- a spelling is priced against the past it is chosen behind (§ The solve).
  -- The placement
  @api sonority.solveToMoves(strands, n, strength, notation, moves, stiffness, ambient)  @ 1224-1243
      -- The moves facility's solve: intervals rather than points, spelled by the beam under a
      -- frozen past, settled by joint relaxation (§ The solve).
      @contract  strands, n, strength, notation, moves, stiffness, ambient → cents settled per strand  @ 1222
      @contract  nil where an onset has no spelling — which is a target stating no move  @ 1223

